___CSS_LOADER_EXPORT___.push([module.id, `.cmsit3d-root {
  --cmsit-purple: #4c2a83;
  position: relative;
  display: flex;
  width: 100%;
  height: 100%;
  min-height: 360px;
  overflow: hidden;
  color: #252b34;
  background: #e7ecf2;
  font-family: Inter, Roboto, Helvetica, Arial, sans-serif;
}

.cmsit3d-sidebar {
  z-index: 4;
  box-sizing: border-box;
  width: 224px;
  min-width: 224px;
  height: 100%;
  padding: 14px 12px;
  overflow-y: auto;
  color: #eef2f7;
  background: #202731;
  border-right: 1px solid #3b4655;
  box-shadow: 5px 0 15px rgba(16, 21, 28, 0.2);
}

.cmsit3d-sidebar-title {
  margin-bottom: 10px;
  font-size: 17px;
  font-weight: 650;
}

.cmsit3d-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}

.cmsit3d-sidebar button {
  min-height: 28px;
  padding: 4px 8px;
  color: #fff;
  background: var(--cmsit-purple);
  border: 1px solid #7555aa;
  border-radius: 4px;
  cursor: pointer;
  font-size: 11px;
}

.cmsit3d-sidebar button:hover {
  background: #5f369e;
}

.cmsit3d-sidebar .cmsit3d-reset {
  width: 100%;
  margin: 6px 0 12px;
  color: #e8edf4;
  background: #303946;
  border-color: #596575;
}

.cmsit3d-control-title {
  margin: 2px 0 5px;
  color: #9eabba;
  font-size: 9px;
  font-weight: 650;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.cmsit3d-mode-switch {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5px;
  margin-bottom: 7px;
}

.cmsit3d-mode-switch button {
  color: #ccd5df;
  background: #303946;
  border-color: #596575;
}

.cmsit3d-mode-switch button.active {
  color: #fff;
  background: var(--cmsit-purple);
  border-color: #8664bd;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.08);
}

.cmsit3d-beam-toggle {
  display: flex;
  align-items: center;
  min-height: 28px;
  margin-bottom: 9px;
  gap: 7px;
  color: #d8dfe8;
  cursor: pointer;
  font-size: 11px;
}

.cmsit3d-beam-toggle input {
  width: 14px;
  height: 14px;
  margin: 0;
  accent-color: var(--cmsit-purple);
}

.cmsit3d-group {
  padding: 8px 0;
  border-top: 1px solid #3b4654;
}

.cmsit3d-group label {
  display: flex;
  align-items: center;
  min-height: 25px;
  gap: 7px;
  cursor: pointer;
  user-select: none;
}

.cmsit3d-group input {
  width: 14px;
  height: 14px;
  margin: 0;
  accent-color: var(--cmsit-purple);
}

.cmsit3d-parent {
  font-weight: 650;
}

.cmsit3d-parent small {
  margin-left: auto;
  color: #aeb8c6;
  font-weight: 400;
}

.cmsit3d-children {
  padding: 3px 0 0 22px;
  color: #d0d7e1;
  font-size: 12px;
}

.cmsit3d-parts-title {
  margin: 7px 0 2px 22px;
  color: #96a3b4;
  font-size: 10px;
  font-weight: 650;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.cmsit3d-parts {
  color: #bdc7d4;
  font-size: 11px;
}

.cmsit3d-help {
  margin-top: 8px;
  padding: 8px;
  color: #bac4d0;
  background: #2a333f;
  border: 1px solid #3d4958;
  border-radius: 4px;
  font-size: 10px;
  line-height: 1.55;
}

.cmsit3d-viewport {
  position: relative;
  flex: 1;
  min-width: 0;
}

.cmsit3d-canvas {
  position: absolute;
  inset: 0;
}

.cmsit3d-canvas canvas {
  display: block;
  width: 100%;
  height: 100%;
  cursor: grab;
}

.cmsit3d-canvas canvas:active {
  cursor: grabbing;
}

.cmsit3d-canvas canvas[data-camera-mode='pan'] {
  cursor: move;
}

.cmsit3d-canvas canvas[data-camera-mode='pan']:active {
  cursor: grabbing;
}

.cmsit3d-status,
.cmsit3d-legend {
  position: absolute;
  z-index: 2;
  display: flex;
  gap: 14px;
  padding: 6px 9px;
  color: #3f4855;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid #ccd2db;
  border-radius: 5px;
  box-shadow: 0 2px 7px rgba(38, 47, 60, 0.1);
  font-size: 11px;
  pointer-events: none;
}

.cmsit3d-status {
  top: 10px;
  left: 10px;
}

.cmsit3d-legend {
  right: 10px;
  bottom: 10px;
}

.cmsit3d-legend span {
  display: flex;
  align-items: center;
  gap: 5px;
}

.cmsit3d-legend i {
  display: inline-block;
  width: 11px;
  height: 11px;
  border: 1px solid rgba(255, 255, 255, 0.38);
  border-radius: 2px;
}

.cmsit3d-tooltip {
  position: fixed;
  z-index: 10000;
  display: flex;
  flex-direction: column;
  max-width: 280px;
  padding: 9px 11px;
  color: #f1f3f5;
  background: rgba(18, 21, 27, 0.96);
  border: 1px solid #596374;
  border-radius: 5px;
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.42);
  font-size: 11px;
  line-height: 1.45;
  pointer-events: none;
}

.cmsit3d-tooltip hr {
  width: 100%;
  margin: 5px 0;
  border: 0;
  border-top: 1px solid rgba(255, 255, 255, 0.16);
}

.cmsit3d-tooltip small {
  margin-top: 4px;
  color: #a8b0bc;
}

@media (max-width: 800px) {
  .cmsit3d-sidebar {
    width: 188px;
    min-width: 188px;
  }
  .cmsit3d-status {
    flex-direction: column;
    gap: 2px;
  }
  .cmsit3d-legend {
    flex-direction: column;
    gap: 3px;
  }
}

.cmsit3d-physical-views {
  position: absolute;
  top: 48px;
  left: 10px;
  right: 10px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: #45556a;
}
.cmsit3d-physical-views button {
  padding: 6px 10px;
  border: 1px solid #adbccd;
  border-radius: 4px;
  background: rgba(255,255,255,0.94);
  color: #26384b;
  cursor: pointer;
}
.cmsit3d-physical-views button:hover { background: #dce9f5; }
.cmsit3d-physical-views span { padding: 5px; background: rgba(255,255,255,0.8); }
@media (max-width: 800px) { .cmsit3d-physical-views { top: 72px; } }
.cmsit3d-group summary, .cmsit3d-element summary { cursor: pointer; padding: 7px 0; }
.cmsit3d-group summary label { display: inline-flex; align-items: center; gap: 7px; }
.cmsit3d-group summary small { float: right; margin: 3px; color: #abb8c8; }
.cmsit3d-element { margin-left: 10px; }
.cmsit3d-element .cmsit3d-children { margin-left: 15px; }
.cmsit3d-inventory { width: 320px; min-width: 280px; max-width: 40%; overflow: auto; padding: 14px; background: #202731; color: #eef2f7; border-left: 1px solid #536071; z-index: 5; font-size: 12px; }
.cmsit3d-inventory-heading { display: flex; justify-content: space-between; align-items: center; font-size: 16px; }
.cmsit3d-inventory button, .cmsit3d-inventory input, .cmsit3d-inventory select { background: #303946; color: #eef2f7; border: 1px solid #637184; border-radius: 4px; padding: 6px; }
.cmsit3d-inventory input:not([type=checkbox]), .cmsit3d-inventory select { display: block; width: 100%; margin: 8px 0; }
.cmsit3d-inventory-note { color: #b2c0d2; line-height: 1.5; }
.cmsit3d-inventory summary { cursor: pointer; padding: 8px 0; }
.cmsit3d-inventory-row { display: block; text-align: left; width: 100%; margin-bottom: 7px; cursor: pointer; }
.cmsit3d-inventory-row span { display: block; margin-top: 4px; font-size: 11px; }
.cmsit3d-inventory-row strong { color: #50dbea; }
.cmsit3d-inventory-issues { color: #ffce82; }
